import { chromium } from 'playwright'
import assert from 'node:assert/strict'
import { mkdir } from 'node:fs/promises'

const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']})
const page=await browser.newPage({viewport:{width:1440,height:900},acceptDownloads:true})
const errors=[]
page.on('pageerror',error=>errors.push(error.message))
page.on('console',message=>{if(message.type()==='error')errors.push(`${message.text()} @ ${message.location().url}`)})
const audit=()=>page.evaluate(()=>window.__nocturneStudioAudit())
const config=()=>page.evaluate(()=>window.__nocturneAudit().config)
const field=(path)=>page.locator(`.studio-field[data-path="${path}"] input[type="number"]`)
const setNumber=async(path,value)=>{await field(path).fill(String(value));await field(path).press('Tab')}
const open=async(name)=>{const details=page.locator(`details[data-category="${name}"]`);if(!(await details.evaluate(element=>element.open)))await details.locator('summary').click()}
try{
  await page.goto('http://127.0.0.1:5173/creator.html',{waitUntil:'domcontentloaded',timeout:60000})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  await page.locator('.creator-panel').waitFor({timeout:60000})
  assert.equal((await audit()).garden.spheres.length,57)
  await open('Particles')
  await setNumber('particles.size',2)
  await setNumber('particles.repulsion',1.4)
  assert.equal((await audit()).garden.particleSize,2)
  assert.equal((await audit()).garden.repulsion,1.4)
  await page.mouse.move(180,480);await page.mouse.move(420,480,{steps:4})
  assert.ok((await audit()).garden.pointerSpeed>0,'Cursor motion must enter the GPU particle simulation')

  await open('Spheres')
  await page.locator('.sphere-list').selectOption('orb-5')
  await page.getByRole('button',{name:'Sphere select'}).click()
  const position=(await audit()).spherePixels.find(s=>s.id==='orb-5')
  const before=(await config()).spheres.find(s=>s.id==='orb-5')
  await page.mouse.move(position.x,position.y);await page.mouse.down();await page.mouse.move(position.x+45,position.y+15,{steps:6})
  assert.ok((await audit()).garden.sphereSpeed>0,'Moving a sphere must send force to nearby particles')
  await page.mouse.up()
  const moved=(await config()).spheres.find(s=>s.id==='orb-5')
  assert.ok(Math.abs(moved.x-before.x)>.01,'Dragging a sphere must change its scene position')
  assert.equal(await page.locator('.sphere-list').inputValue(),'orb-5')
  const handle=await page.getByRole('button',{name:'Resize selected sphere'}).boundingBox()
  assert.ok(handle,'Selected sphere must have a direct resize handle')
  await page.mouse.move(handle.x+handle.width/2,handle.y+handle.height/2);await page.mouse.down();await page.mouse.move(handle.x+handle.width/2,handle.y-35,{steps:5});await page.mouse.up()
  assert.ok((await config()).spheres.find(s=>s.id==='orb-5').size>before.size,'Handle must resize sphere')
  const resized=(await config()).spheres.find(s=>s.id==='orb-5').size
  await page.getByRole('button',{name:'Undo'}).dispatchEvent('click')
  assert.ok((await config()).spheres.find(s=>s.id==='orb-5').size<resized,'Undo must restore sphere size')
  await page.getByRole('button',{name:'Redo'}).dispatchEvent('click')
  assert.equal((await config()).spheres.find(s=>s.id==='orb-5').size,resized,'Redo must restore sphere edit')
  await page.getByRole('button',{name:'Save',exact:true}).click()
  const saved=(await config()).spheres.find(s=>s.id==='orb-5')
  await page.reload({waitUntil:'domcontentloaded',timeout:60000})
  await page.locator('.creator-panel').waitFor({timeout:60000})
  assert.equal((await config()).spheres.find(s=>s.id==='orb-5').x,saved.x,'Sphere position must survive refresh')

  await open('Bottle')
  await setNumber('bottle.inertia',3)
  await setNumber('bottle.damping',1)
  await setNumber('bottle.momentumSensitivity',2)
  const bottleBounds=await page.locator('.bottle-drag-target').boundingBox()
  const bottleX=bottleBounds.x+bottleBounds.width/2,bottleY=bottleBounds.y+bottleBounds.height/2
  await page.mouse.move(bottleX,bottleY);await page.mouse.down();await page.mouse.move(bottleX+90,bottleY,{steps:3});await page.mouse.up()
  const released=await page.evaluate(()=>window.__nocturneAudit().rotation)
  assert.ok(Math.abs((await audit()).bottle.angularVelocity)>.001,'Flick must preserve angular velocity on release')
  await page.waitForFunction(initial=>Math.abs(window.__nocturneStudioAudit().bottle.yaw-initial)>.005,released,{timeout:10000})
  await setNumber('bottle.glassIor',1.65)
  assert.equal((await audit()).bottle.glass.ior,1.65)
  assert.equal((await config()).bottle.inertia,3)
  await open('Lighting');await setNumber('lighting.key',3.1)
  assert.equal((await audit()).lights.key,3.1)
  await open('Atmosphere');await setNumber('atmosphere.brightness',1.2)
  assert.equal((await audit()).look.brightness,1.2)
  await open('Camera');await setNumber('camera.fov',42)
  assert.equal((await audit()).camera.fov,42)
  await page.getByRole('button',{name:'Paint',exact:true}).click()
  await page.mouse.move(150,400);await page.mouse.down();await page.mouse.move(180,410,{steps:3});await page.mouse.up()
  assert.ok((await audit()).brushStrokes>0,'Brush must add localized grading strokes')
  assert.equal((await audit()).look.strokes,(await audit()).brushStrokes,'Brush strokes must enter the film shader')
  await page.getByRole('button',{name:'Preview'}).click()
  assert.ok(await page.locator('body.creator-preview').count())
  assert.ok(await page.getByRole('button',{name:'Open Creator Studio'}).isVisible())
  await page.getByRole('button',{name:'Open Creator Studio'}).click()
  await open('Presets')
  page.once('dialog',dialog=>dialog.accept('CI review preset'))
  await page.getByRole('button',{name:'Save As'}).click()
  assert.equal(await page.getByRole('combobox',{name:'Saved presets'}).inputValue(),'CI review preset')
  await open('Lighting');await setNumber('lighting.key',1.6)
  await page.getByRole('button',{name:'Load',exact:true}).click()
  assert.equal((await audit()).lights.key,3.1,'Loading a preset must restore rendered light values')
  const imported=await config()
  await setNumber('lighting.key',1.3)
  await page.locator('.preset-tools input[type=file]').setInputFiles({name:'visitor-scene.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(imported))})
  await page.waitForFunction(()=>window.__nocturneStudioAudit().lights.key===3.1)
  assert.equal((await audit()).lights.key,3.1,'JSON import must restore the actual scene')
  await open('Spheres');await page.locator('.sphere-list').selectOption('orb-5')
  const count=(await audit()).garden.spheres.length
  await page.getByRole('button',{name:'Duplicate',exact:true}).first().click()
  assert.equal((await audit()).garden.spheres.length,count+1,'Duplicating a sphere must add a rendered mesh')
  await page.getByRole('button',{name:'Delete',exact:true}).click()
  assert.equal((await audit()).garden.spheres.length,count,'Deleting a sphere must remove its rendered mesh')
  await page.locator('.sphere-list').selectOption('orb-5')
  await page.locator('.studio-field[data-path="spheres.4.locked"] input[type=checkbox]').check()
  await page.getByRole('button',{name:'Sphere select'}).click()
  const locked=(await config()).spheres.find(s=>s.id==='orb-5').x
  const point=(await audit()).spherePixels.find(s=>s.id==='orb-5')
  await page.mouse.move(point.x,point.y);await page.mouse.down();await page.mouse.move(point.x+30,point.y,{steps:3});await page.mouse.up()
  assert.equal((await config()).spheres.find(s=>s.id==='orb-5').x,locked,'Locked sphere must resist direct dragging')
  await page.getByRole('button',{name:'Sphere select'}).click()
  const downloadPromise=page.waitForEvent('download')
  await page.getByRole('button',{name:'Export JSON'}).click()
  const download=await downloadPromise
  assert.equal(download.suggestedFilename(),'visitor-scene.json')
  await mkdir('.github/preview',{recursive:true})
  await page.screenshot({path:'.github/preview/creator-studio.png',timeout:120000,animations:'disabled'})

  await page.setViewportSize({width:390,height:844})
  await page.reload({waitUntil:'domcontentloaded',timeout:60000})
  await page.locator('.creator-panel').waitFor({timeout:60000})
  const panel=await page.locator('.creator-panel').boundingBox()
  assert.ok(panel&&panel.x>=0&&panel.x+panel.width<=391,'Mobile editor must fit the viewport')
  assert.ok((await audit()).garden.drawCount<=9216,'Mobile particle count must remain bounded')
  assert.ok((await audit()).brushStrokes>0,'Painted strokes must survive refresh')
  await page.screenshot({path:'.github/preview/creator-mobile.png',timeout:120000,animations:'disabled'})

  await page.goto('http://127.0.0.1:5173/',{waitUntil:'domcontentloaded',timeout:60000})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  assert.equal(await page.locator('.creator-panel').count(),0,'Visitor mode must not expose Creator Studio')
  assert.deepEqual(errors,[],'Creator and visitor pages must have no runtime or shader errors')
  console.log('PASS: sphere drag/resize/save, GPU controls, materials, lighting, atmosphere, camera, brush, undo/redo, preset, export, preview and visitor isolation.')
}finally{await browser.close()}
